mapper.select:
SELECT DATE_FORMAT(access_time, '%H:00') AS time, COUNT(*) AS count FROM vehicle_access WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY DATE_FORMAT(access_time, '%H:00') ORDER BY time

SELECT DATE_FORMAT(access_time, '%Y-%m-%d') AS date, SUM(CASE WHEN access_status = '进场中' THEN 1 ELSE 0 END) AS inCount, SUM(CASE WHEN access_status IN ('出场中', '已离场') THEN 1 ELSE 0 END) AS outCount FROM vehicle_access WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY DATE_FORMAT(access_time, '%Y-%m-%d') ORDER BY date

SELECT park_name AS parkName, COUNT(*) AS count FROM vehicle_access WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY park_name ORDER BY count DESC

SELECT vehicle_type AS name, COUNT(*) AS value FROM vehicle_access WHERE deleted = FALSE
AND access_time >= #{startTime}
AND access_time <= #{endTime}
GROUP BY vehicle_type ORDER BY value DESC
